insert into public.site_content(key,data) values('general','{"brand":"Timberline","brand_sub":"HOMES","tagline":"Timber-frame homes","primary_color":"#2a2c2f","accent_color":"#c8844a","announcement_on":false,"announcement_text":"Spring offer: free site survey","announcement_link":"/contact","footer_text":"© 2026 Timberline Homes. All rights reserved."}'::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('seo','{"meta_title":"Timberline Homes — Timber-frame houses, turnkey in 2 months","meta_description":"Energy-efficient timber-frame homes built turnkey in as little as 2 months.","og_image":"https://images.unsplash.com/photo-1568605114967-8130f3a36994?auto=format&fit=crop&w=1200&q=80"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('contact','{"phone":"+1 (555) 989-9889","email":"hello@timberline.demo","address":"12 Pine Ridge Road, Portland, OR","hours":"Mon–Fri 9:00–18:00","map_embed_url":"","instagram":"#","facebook":"#"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('hero','{"title":"A ready timber-frame home\nfrom 1,100 sq ft, turnkey in 2 months","text":"We build thoughtful, eco-friendly homes with high energy efficiency for comfortable family living.","cta_label":"Request a quote","cta_link":"/contact","image":"https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=1000&q=80"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('tech','{"title":"We build homes\nusing timber-frame technology","text":"Cottages and saunas built with timber-frame technology are popular worldwide, and some have stood for centuries.","image":"https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=1000&q=80"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('catalog','{"title":"Our project catalog\nfor 2024","side_title":"Timber-frame construction","side_sub":"at the peak of its popularity","cta_label":"View catalog"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('payments','{"title":"Ways to pay"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content(key,data) values('steps','{"title":"Three steps to your new home"}'::jsonb) on conflict (key) do nothing;
insert into public.stats(sort_order,published,value,suffix,label,image) select sort_order,published,value,suffix,label,image from jsonb_populate_recordset(null::public.stats,'[{"sort_order":1,"published":true,"value":"65","suffix":"~","label":"average days to build","image":"https://images.unsplash.com/photo-1480074568708-e7b720bb3f09?auto=format&fit=crop&w=200&q=80"},{"sort_order":2,"published":true,"value":"7","suffix":"+","label":"years of warranty on every home","image":"https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=200&q=80"},{"sort_order":3,"published":true,"value":"180","suffix":"+","label":"homes built since 2013","image":"https://images.unsplash.com/photo-1518780664697-55e3ad937233?auto=format&fit=crop&w=200&q=80"}]'::jsonb) where not exists (select 1 from public.stats);
insert into public.features(sort_order,published,title,text,image) select sort_order,published,title,text,image from jsonb_populate_recordset(null::public.features,'[{"sort_order":1,"published":true,"title":"High strength","text":"Resistant to cracks and deformation.","image":"https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=200&q=80"},{"sort_order":2,"published":true,"title":"Thermal insulation","text":"Warms up fast and holds heat for long.","image":"https://images.unsplash.com/photo-1523217582562-09d0def993a6?auto=format&fit=crop&w=200&q=80"},{"sort_order":3,"published":true,"title":"No settling","text":"Move in right after the finishing work.","image":"https://images.unsplash.com/photo-1448630360428-65456885c650?auto=format&fit=crop&w=200&q=80"}]'::jsonb) where not exists (select 1 from public.features);
insert into public.projects(sort_order,published,title,price,image,description) select sort_order,published,title,price,image,description from jsonb_populate_recordset(null::public.projects,'[{"sort_order":1,"published":true,"title":"Timber house, 830 sq ft","price":"from $72,000","image":"https://images.unsplash.com/photo-1518780664697-55e3ad937233?auto=format&fit=crop&w=900&q=80","description":"Compact dark-clad A-frame cottage."},{"sort_order":2,"published":true,"title":"Timber house, 1,010 sq ft","price":"from $96,000","image":"https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=900&q=80","description":"Glass-front modern two-storey home."},{"sort_order":3,"published":true,"title":"Timber house, 700 sq ft","price":"from $80,000","image":"https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=900&q=80","description":"Cantilevered balcony house in the pines."},{"sort_order":4,"published":true,"title":"Timber house, 650 sq ft","price":"from $69,000","image":"https://images.unsplash.com/photo-1480074568708-e7b720bb3f09?auto=format&fit=crop&w=900&q=80","description":"Gabled wood-clad family cabin."}]'::jsonb) where not exists (select 1 from public.projects);
insert into public.payments(sort_order,published,title,text) select sort_order,published,title,text from jsonb_populate_recordset(null::public.payments,'[{"sort_order":1,"published":true,"title":"Home loan","text":"We partner with several major banks offering loans from 5.5% a year."},{"sort_order":2,"published":true,"title":"Family capital","text":"Use state family capital towards building your home."},{"sort_order":3,"published":true,"title":"Subsidies","text":"We work with government subsidy programs. Call us for details."},{"sort_order":4,"published":true,"title":"Bank transfer","text":"Sign a contract with the company and pay for work by invoice."}]'::jsonb) where not exists (select 1 from public.payments);
insert into public.steps(sort_order,published,title,text) select sort_order,published,title,text from jsonb_populate_recordset(null::public.steps,'[{"sort_order":1,"published":true,"title":"Consultation\nand design","text":"Share your wishes and budget, and get a tailored project proposal."},{"sort_order":2,"published":true,"title":"Construction","text":"Our team builds the frame house on schedule with quality control."},{"sort_order":3,"published":true,"title":"Finishing","text":"We complete interior and exterior finishing and hand over the keys."}]'::jsonb) where not exists (select 1 from public.steps);
